@Service
public class BOMService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public BOMService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new BOMEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(BOMRepository.class) );
		this.validator		= applicationContext.getBean(BOMValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		BOM
	 */
		public BOM createBOM( CreateBOMCommand command ) {

		BOM entity = new BOM();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setBOMId( command.getBOMId() );
            entity.setBomNumber( command.getBomNumber() );
            entity.setRevision( command.getRevision() );
            entity.setEffectivityStart( command.getEffectivityStart() );
            entity.setEffectivityEnd( command.getEffectivityEnd() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of BOM {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateBOMCommand
	 * @return		BOM
	 */
	public BOM updateBOM( UpdateBOMCommand command ) {

		BOM entity = new BOM();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setBOMId( command.getBOMId() );
            entity.setBomNumber( command.getBomNumber() );
            entity.setRevision( command.getRevision() );
            entity.setEffectivityStart( command.getEffectivityStart() );
            entity.setEffectivityEnd( command.getEffectivityEnd() );
            entity.setParentItem( command.getParentItem() );
            entity.setBomItems( command.getBomItems() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of BOM {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteBOMCommand
	 */
	public void delete( DeleteBOMCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getBOMId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of BOM {0} ", id );

	}

	/**
	 * Method to retrieve the BOM via BOMFetchOneSummary
	 * @param 	summary BOMFetchOneSummary
	 * @return 	BOMFetchOneResponse
	 */
	public BOM getBOM( BOMFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "BOMFetchOneSummary arg cannot be null" );

		BOM entity = null;
		UUID id = summary.getBOMId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a BOM using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all BOMs
	 *
	 * @return 	List<BOM>
	 */
    public List<BOM> getAllBOM() {
		List<BOM> list = projector.findAll( new FindAllBOMQuery() );
		return list;
	}

	/**
	 * assign ParentItem on BOM
	 * @param		command AssignParentItemToBOMCommand
	 */
	public void assignParentItem( AssignParentItemToBOMCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignParentItem(command.getBOMId(), command.getAssignment());

	}

	/**
	 * unAssign ParentItem on BOM
	 * @param		command UnAssignParentItemFromBOMCommand
	 */
	public void unAssignParentItem( UnAssignParentItemFromBOMCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignParentItem(command.getBOMId());
	}
	

	/**
	 * add BOMItem to BomItems
	 * @param		command AssignBomItemsToBOMCommand
	 */
	public void addToBomItems( AssignBomItemsToBOMCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToBomItems(command.getBOMId(), command.getAddTo());
	}

	/**
	 * remove BOMItem from BomItems
	 * @param		command RemoveBomItemsFromBOMCommand
	 */
	public void removeFromBomItems( RemoveBomItemsFromBOMCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromBomItems(command.getBOMId(), command.getRemoveFrom());
	}




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final BOMEntityProjector projector;
	private final BOMValidator validator;
	private BOM bOM 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(BOMService.class);
}
